CREATE TABLE IF NOT EXISTS gis_official_source_registry (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_key text UNIQUE NOT NULL, authority_name text NOT NULL, source_title text NOT NULL, source_url text NOT NULL, hierarchy text NOT NULL, authority_level text NOT NULL, acquisition_status text NOT NULL DEFAULT 'DISCOVERED', artifact_sha256 text, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());